"""Reproduzierbare Anwendung der nach vollständiger Lektüre festgelegten Zuordnungen.
Keine Stichwortklassifikation: Entscheidungen sind ausdrücklich an Punkt-/Abschnitts-
und Zeilennummern gebunden. Änderungen der Originale werden durch Prüfsummen abgewiesen.
"""
import collections,hashlib,json,re,subprocess,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
D=ROOT/'docs/einsamkeit'
read=lambda p:json.loads(p.read_text())
rows=[json.loads(l) for l in (D/'bestandsaufnahme.jsonl').read_text().splitlines()]
registry=read(D/'quellenregister.json')
nodes=[]
def walk(items,parents=[]):
 for n in items:
  nodes.append(dict(n,parents=parents));walk(n['children'],parents+[n])
walk(read(ROOT/'frontend/lib/loneliness-topics.json'))
by_num={n['conceptNumber']:n for n in nodes};by_id={n['id']:n for n in nodes}
raw_fields=['id','datei','fundstelle','quellabschnitt','original']
baseline=[json.loads(l) for l in subprocess.check_output(['git','show','2cdd58be5a6a3a75fc6d4081d3070c256995e16b:docs/einsamkeit/bestandsaufnahme.jsonl'],cwd=ROOT,text=True).splitlines()]
assert [[r[k] for k in raw_fields] for r in rows]==[[r[k] for k in raw_fields] for r in baseline]
old={r['id']:r for r in baseline};spec={}
def put(source,line,targets,kind='themenplanung',form='rechercheauftrag',note=''):
 key=f'{source}-L{line}';assert key in old,key
 spec[key]={'targets':list(dict.fromkeys(targets.split(','))) if targets else [],'arten':kind.split(','),'form':form,'note':note}
def blocks(source,start,end,targets,kind,form,note):
 for r in rows:
  if r['datei']==source and start<=int(r['fundstelle'].split()[1])<=end:put(source,int(r['fundstelle'].split()[1]),targets,kind,form,note)
def point_map(source,table,kind='themenplanung',form='rechercheauftrag'):
 points={}
 for a,b,targets in table:
  for i in range(a,b+1):assert i not in points,(source,i);points[i]=targets
 for r in rows:
  if r['datei']==source and (m:=re.match(r'(\d+)\\?\. ',r['original'])):
   i=int(m[1]);assert i in points,(source,i)
   put(source,int(r['fundstelle'].split()[1]),points[i],kind,form,f'Einzelpunkt {i}: Inhalt und Quellabschnitt gelesen; Schwerpunkt und zusätzliche Aspekte anhand der bestehenden Konzeptknoten erschlossen.')
 return points
# B1: sämtliche 270 Einzelentscheidungen des vorherigen Durchgangs erneut gelesen.
for r in baseline:
 if r['datei']=='B1' and re.match(r'\d+\. ',r['original']):
  targets=','.join(by_id[i]['conceptNumber'] for i in r['zuordnungen'])
  put('B1',int(r['fundstelle'].split()[1]),targets,note='B1-Einzelpunkt erneut inhaltlich gegen Gesamtkonzeption geprüft. Themenbezeichnung ist Rechercheplanung, keine bestätigte Tatsachenaussage.')
