# Aussageart präzisieren. Inhaltliche Auswahl erfolgte beim Lesen, nicht durch Worttreffer.
def tag(source,lines,kinds,form=None,replace=False):
 for line in lines:
  s=spec[f'{source}-L{line}'];s['arten']=kinds.split(',') if replace else list(dict.fromkeys(s['arten']+kinds.split(',')))
  if form:s['form']=form
for s in spec.values():
 s['arten']=['wissenschaftlicher_bezug' if k=='wissenschaftliche_aussage' else k for k in s['arten']]
# B1/B2 sind in erster Linie Recherchelisten, nicht eine Sammlung verifizierter Ergebnisse.
for source in ['B1','B2']:
 for key,s in spec.items():
  if not key.startswith(source+'-'):continue
  if any(t.split('.')[0] in ['5','13'] for t in s['targets']):s['arten'].append('wissenschaftlicher_bezug')
  if any(t.startswith('2.5') or t=='10.6' for t in s['targets']):s['arten'].append('historischer_recherchebedarf')
  if any(t.startswith('15.') for t in s['targets']):s['arten'].append('politischer_bezug')
  if any(t.startswith('17.3') for t in s['targets']):s['arten'].append('veranstaltungsnotiz')
